#!/usr/bin/env node
/*
 * End-to-end verification for Northwind Stays.
 *
 *   node build.js
 *   python make_sheets.py --base-url <any>      (writes verify/test_rows.json)
 *   node verify/verify.js [--no-edge] [--live https://USERNAME.github.io/northwind-stays]
 *
 * Serves docs/ on a local port, runs every sheet row (as structured steps
 * generated by make_sheets.py) in a fresh 1280x800 browser context, audits
 * every page, scans the deployed files, checks the .xlsx files and writes
 * VERIFY_REPORT.md. Exit code 0 only when every expectation holds.
 */
'use strict';

const fs = require('fs');
const path = require('path');
const http = require('http');
const { execSync, spawnSync } = require('child_process');

function loadPlaywright() {
  let dir;
  try {
    dir = path.dirname(require.resolve('playwright/package.json'));
  } catch (e) {
    dir = path.join(execSync('npm root -g').toString().trim(), 'playwright');
  }
  return { lib: require(dir), version: require(path.join(dir, 'package.json')).version };
}

const { lib: playwright, version: PLAYWRIGHT_VERSION } = loadPlaywright();
const ROOT = path.resolve(__dirname, '..');
const DOCS = path.join(ROOT, 'docs');
const OUT = path.join(__dirname, 'out');
const ROWS = JSON.parse(fs.readFileSync(path.join(__dirname, 'test_rows.json'), 'utf8'));
const BUILDS = { v1: '1.0.0', v2: '1.1.0' };
const BANNER = 'Northwind Stays is a fictional test website for UAT practice. No real bookings, payments or personal data.';
const SIGNED_IN_PAGES = ['search.html', 'results.html', 'details.html', 'book.html', 'confirmation.html', 'bookings.html'];
const CHECK_TIMEOUT = 4000;
const CONCURRENCY = 4;
const LEAK_WORDS = /regress|\bbugs?\b|buggy|planted|defect|intentional|deliberat|sabotag|\bR[123]\b|answer.?key|known.?issue|\bflaw|faulty|broken|fixme|\btodo\b|\bhack|mistake|off.by.one|inject|seeded|\bwrong\b|incorrect total|ignores? rooms/i;

/* ---------------- static server ---------------- */

function startServer() {
  const types = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };
  const server = http.createServer(function (req, res) {
    const pathname = decodeURIComponent(new URL(req.url, 'http://local').pathname);
    let file = path.join(DOCS, pathname);
    if (!file.startsWith(DOCS)) { res.writeHead(403); res.end(); return; }
    if (fs.existsSync(file) && fs.statSync(file).isDirectory()) file = path.join(file, 'index.html');
    if (!fs.existsSync(file)) { res.writeHead(404); res.end('Not found'); return; }
    res.writeHead(200, { 'Content-Type': types[path.extname(file)] || 'application/octet-stream', 'Cache-Control': 'no-store' });
    fs.createReadStream(file).pipe(res);
  });
  return new Promise(function (resolve) {
    server.listen(0, '127.0.0.1', function () { resolve(server); });
  });
}

/* ---------------- helpers ---------------- */

const externalRequests = new Set();
const allowedHosts = new Set(['127.0.0.1']);

function sleep(ms) {
  return new Promise(function (r) { setTimeout(r, ms); });
}

async function until(describe, fn) {
  const end = Date.now() + CHECK_TIMEOUT;
  let detail = '';
  for (;;) {
    try {
      const result = await fn();
      if (result === true) return;
      detail = result || '';
    } catch (e) {
      detail = e.message.split('\n')[0];
    }
    if (Date.now() > end) throw new Error(describe + (detail ? ' (' + detail + ')' : ''));
    await sleep(100);
  }
}

async function newContext(browser) {
  const context = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  context.setDefaultTimeout(CHECK_TIMEOUT);
  const problems = [];
  await context.route('**/*', function (route) {
    const url = new URL(route.request().url());
    if (url.protocol === 'data:' || allowedHosts.has(url.hostname)) return route.continue();
    externalRequests.add(route.request().url());
    problems.push('external request blocked: ' + route.request().url());
    return route.abort();
  });
  context.on('page', function (page) {
    page.on('pageerror', function (e) { problems.push('page error: ' + e.message); });
    page.on('console', function (m) { if (m.type() === 'error') problems.push('console error: ' + m.text()); });
    page.on('dialog', function (d) { problems.push('dialog shown: ' + d.message()); d.dismiss().catch(function () {}); });
  });
  return { context: context, problems: problems };
}

async function goto(page, url) {
  try {
    await page.goto(url, { waitUntil: 'load' });
  } catch (e) {
    if (!/interrupted|ERR_ABORTED/.test(e.message)) throw e;
  }
  await page.waitForLoadState('load');
}

async function visibleTexts(locator) {
  const out = [];
  const count = await locator.count();
  for (let i = 0; i < count; i++) {
    const item = locator.nth(i);
    if (await item.isVisible()) out.push((await item.innerText()).trim());
  }
  return out;
}

async function cardNames(page) {
  return visibleTexts(page.locator('[data-testid="property-card"] [data-testid="property-name"]'));
}

async function anyVisible(locator) {
  const count = await locator.count();
  for (let i = 0; i < count; i++) {
    if (await locator.nth(i).isVisible()) return true;
  }
  return false;
}

function card(page, name) {
  return page.locator('[data-testid="property-card"]').filter({ has: page.getByRole('heading', { name: name, exact: true }) });
}

/* ---------------- steps and checks ---------------- */

async function clickMaybeNavigate(page, locator, nav) {
  if (!nav) {
    await locator.click();
    return;
  }
  const before = page.url();
  await Promise.all([
    page.waitForURL(function (u) { return u.toString() !== before; }, { waitUntil: 'load' }),
    locator.click()
  ]);
}

async function runStep(page, base, build, step) {
  switch (step.op) {
    case 'open':
      return goto(page, base + '/' + build + '/' + step.path);
    case 'fill':
      return page.getByLabel(step.label, { exact: true }).fill(step.value);
    case 'select':
      return page.getByLabel(step.label, { exact: true }).selectOption({ label: step.option });
    case 'tick':
      return page.getByLabel(step.label, { exact: true }).check();
    case 'click':
      return clickMaybeNavigate(page, page.getByRole(step.role, { name: step.name, exact: true }), step.nav);
    case 'click_card':
      return clickMaybeNavigate(page, card(page, step.card).getByRole(step.role, { name: step.name, exact: true }), step.nav);
    case 'check':
      for (const check of step.checks) await runCheck(page, check);
      return undefined;
    default:
      throw new Error('unknown step ' + step.op);
  }
}

async function runCheck(page, check) {
  switch (check.type) {
    case 'heading':
      return until('page heading should be "' + check.text + '"', async function () {
        const found = await visibleTexts(page.locator('h1'));
        return found.indexOf(check.text) !== -1 || 'found ' + JSON.stringify(found);
      });
    case 'shows':
      return until('"' + check.text + '" should be shown', async function () {
        return anyVisible(page.getByText(check.text, { exact: true }));
      });
    case 'not_shows':
      return until('"' + check.text + '" should not be shown', async function () {
        return !(await anyVisible(page.getByText(check.text, { exact: true })));
      });
    case 'count':
      return until('results line should read "' + check.text + '"', async function () {
        const text = (await page.getByTestId('result-count').innerText()).trim();
        return text === check.text || 'found "' + text + '"';
      });
    case 'results':
      return until('results should be exactly ' + JSON.stringify(check.names), async function () {
        const found = await cardNames(page);
        return JSON.stringify(found.slice().sort()) === JSON.stringify(check.names.slice().sort()) || 'found ' + JSON.stringify(found);
      });
    case 'first_last':
      return until('first/last should be ' + check.first + ' / ' + check.last, async function () {
        const found = await cardNames(page);
        return (found[0] === check.first && found[found.length - 1] === check.last) || 'found ' + JSON.stringify(found);
      });
    case 'checked':
      return until('checkbox ' + check.label + ' should be ' + (check.value ? 'ticked' : 'unticked'), async function () {
        const state = await page.getByLabel(check.label, { exact: true }).isChecked();
        return state === check.value || 'it is ' + (state ? 'ticked' : 'unticked');
      });
    case 'button':
      return until('"' + check.name + '" button should be ' + (check.present ? 'shown' : 'absent'), async function () {
        const shown = (await anyVisible(page.getByRole('button', { name: check.name, exact: true }))) ||
          (await anyVisible(page.getByRole('link', { name: check.name, exact: true })));
        return shown === check.present;
      });
    case 'card_badge':
      return until(check.card + ' card badge should be ' + (check.present ? 'shown' : 'absent'), async function () {
        const target = card(page, check.card);
        if ((await target.count()) !== 1) return 'card not found';
        return (await anyVisible(target.getByText(check.text, { exact: true }))) === check.present;
      });
    case 'page':
      return until('address should show ' + check.path, async function () {
        return new URL(page.url()).pathname.endsWith('/' + check.path) || 'at ' + page.url();
      });
    case 'field':
      return until(check.label + ' field should be visible', async function () {
        return page.getByLabel(check.label, { exact: true }).isVisible();
      });
    default:
      throw new Error('unknown check ' + check.type);
  }
}

async function runRow(browser, base, build, row, tag) {
  const { context, problems } = await newContext(browser);
  const page = await context.newPage();
  let error = null;
  try {
    for (const step of row.steps) await runStep(page, base, build, step);
    for (const check of row.checks) await runCheck(page, check);
  } catch (e) {
    error = e.message.split('\n')[0];
  }
  if (!error && problems.length) error = problems.join('; ');
  if (error) {
    fs.mkdirSync(OUT, { recursive: true });
    await page.screenshot({ path: path.join(OUT, tag + '-' + build + '-' + row.id + '.png'), fullPage: true }).catch(function () {});
  }
  await context.close();
  return { id: row.id, feature: row.feature, smoke: row.smoke, failsOn: row.failsOn, pass: !error, error: error };
}

async function runSuite(browser, base, build, rows, tag) {
  const results = new Array(rows.length);
  let next = 0;
  async function worker() {
    while (next < rows.length) {
      const index = next++;
      results[index] = await runRow(browser, base, build, rows[index], tag);
    }
  }
  await Promise.all(Array.from({ length: CONCURRENCY }, worker));
  return results;
}

/* ---------------- page audit ---------------- */

async function auditPages(browser, base) {
  const results = [];
  for (const build of Object.keys(BUILDS)) {
    const files = fs.readdirSync(path.join(DOCS, build)).filter(function (f) { return f.endsWith('.html'); }).sort();
    for (const file of files) {
      const { context, problems } = await newContext(browser);
      const page = await context.newPage();
      const notes = [];
      try {
        const raw = fs.readFileSync(path.join(DOCS, build, file), 'utf8');
        if (raw.indexOf(BANNER) === -1) notes.push('banner missing from HTML');
        if (raw.indexOf('Build ' + BUILDS[build]) === -1) notes.push('build label missing from HTML');
        if (file === 'otp.html') {
          await goto(page, base + '/' + build + '/login.html');
          await page.getByLabel('Email', { exact: true }).fill('tester@northwind.test');
          await page.getByLabel('Password', { exact: true }).fill('Test@1234');
          await clickMaybeNavigate(page, page.getByRole('button', { name: 'Log in', exact: true }), true);
        } else {
          await goto(page, base + '/' + build + '/' + file + (SIGNED_IN_PAGES.indexOf(file) !== -1 ? '?as=tester' : ''));
        }
        await page.waitForLoadState('load');
        const landed = path.basename(new URL(page.url()).pathname) || 'index.html';
        const expectedLanding = file === 'index.html' ? 'login.html' : file;
        if (landed !== expectedLanding) notes.push('landed on ' + landed);
        const banner = page.getByText(BANNER, { exact: true });
        if (!(await anyVisible(banner))) notes.push('banner not visible');
        else if ((await banner.first().boundingBox()).y > 2) notes.push('banner not at top of page');
        const label = (await page.getByTestId('build-label').innerText()).trim();
        if (label !== 'Build ' + BUILDS[build]) notes.push('footer label is "' + label + '"');
        const unlabelled = await page.evaluate(function () {
          return Array.from(document.querySelectorAll('input, select, textarea')).filter(function (el) {
            const label = el.id && document.querySelector('label[for="' + el.id + '"]');
            return !label || !label.textContent.trim();
          }).map(function (el) { return el.id || el.name || el.tagName; });
        });
        if (unlabelled.length) notes.push('inputs without <label for>: ' + unlabelled.join(', '));
      } catch (e) {
        notes.push(e.message.split('\n')[0]);
      }
      if (problems.length) notes.push(problems.join('; '));
      results.push({ page: build + '/' + file, pass: notes.length === 0, notes: notes.join('; ') });
      await context.close();
    }
  }

  const { context, problems } = await newContext(browser);
  const page = await context.newPage();
  const notes = [];
  await goto(page, base + '/index.html');
  if (!(await anyVisible(page.getByText(BANNER, { exact: true })))) notes.push('banner not visible');
  for (const build of Object.keys(BUILDS)) {
    const href = await page.getByRole('link', { name: 'Open Build ' + BUILDS[build], exact: true }).getAttribute('href');
    if (href !== build + '/login.html') notes.push('link for ' + build + ' is ' + href);
  }
  if (problems.length) notes.push(problems.join('; '));
  results.push({ page: 'index.html (landing)', pass: notes.length === 0, notes: notes.join('; ') });
  await context.close();
  return results;
}

/* ---------------- static scans ---------------- */

function walk(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap(function (entry) {
    const full = path.join(dir, entry.name);
    return entry.isDirectory() ? walk(full) : [full];
  });
}

function scanDeployedFiles() {
  const findings = [];
  const files = walk(DOCS);
  files.forEach(function (file) {
    const rel = path.relative(DOCS, file).split(path.sep).join('/');
    const text = fs.readFileSync(file, 'utf8');
    const nameHit = LEAK_WORDS.exec(rel);
    if (nameHit) findings.push(rel + ': file name contains "' + nameHit[0] + '"');
    text.split('\n').forEach(function (line, i) {
      const hit = LEAK_WORDS.exec(line);
      if (hit) findings.push(rel + ':' + (i + 1) + ' contains "' + hit[0] + '"');
      if (/https?:\/\/|(?:src|href)\s*=\s*["']\/\//i.test(line)) findings.push(rel + ':' + (i + 1) + ' references an absolute URL');
      if (/\b(alert|confirm|prompt)\s*\(|Math\.random|<img\b|<iframe\b|@import|url\(/.test(line)) findings.push(rel + ':' + (i + 1) + ' uses a disallowed construct');
      if (/\{\{\w+\}\}|#(if|else|endif)\b/.test(line)) findings.push(rel + ':' + (i + 1) + ' has an unprocessed build token');
    });
  });
  return { files: files.length, findings: findings };
}

function checkSheets() {
  const result = spawnSync('python', [path.join(__dirname, 'check_sheets.py'), '--base-url', ROWS.baseUrl], { encoding: 'utf8' });
  try {
    return JSON.parse(result.stdout);
  } catch (e) {
    return { ok: false, checks: [{ name: 'run check_sheets.py', ok: false, detail: (result.stderr || result.stdout || '').trim() }] };
  }
}

/* ---------------- report ---------------- */

function judge(core1, core2, feat2) {
  const expectedV2 = ROWS.core.filter(function (r) { return r.failsOn.indexOf('v2') !== -1; }).map(function (r) { return r.id; });
  const failedV2 = core2.filter(function (r) { return !r.pass; }).map(function (r) { return r.id; });
  return {
    v1AllPass: core1.every(function (r) { return r.pass; }),
    v2ExactFails: JSON.stringify(failedV2) === JSON.stringify(expectedV2),
    v2SmokePass: core2.filter(function (r) { return r.smoke; }).every(function (r) { return r.pass; }),
    featureAllPass: feat2.every(function (r) { return r.pass; }),
    expectedV2: expectedV2,
    failedV2: failedV2
  };
}

function cell(text) {
  return String(text || '').replace(/\|/g, '\\|').replace(/\n/g, ' ');
}

function mark(ok) {
  return ok ? 'PASS' : 'FAIL';
}

function writeReport(runs, audit, scan, sheets, info) {
  const main = runs[0];
  const lines = [];
  const verdict = runs.every(function (run) {
    const j = run.judgement;
    return j.v1AllPass && j.v2ExactFails && j.v2SmokePass && j.featureAllPass;
  }) && audit.every(function (a) { return a.pass; }) && scan.findings.length === 0 && externalRequests.size === 0 && sheets.ok;

  lines.push('# Northwind Stays verification report', '');
  lines.push('Generated ' + info.date + ' by `node verify/verify.js` against a local static server serving `docs/`' +
    (info.live ? ' and against the live site at ' + info.live : '') + '. Viewport 1280x800, one fresh browser context per row.', '');
  lines.push('Browsers: ' + runs.map(function (r) { return r.label; }).join(', ') + '. Playwright ' + info.playwright + '.', '');
  lines.push('**Overall result: ' + (verdict ? 'PASS, every expectation holds' : 'FAIL, see below') + '**', '');

  lines.push('## Summary', '');
  lines.push('| Check | Expected | Result |', '|---|---|---|');
  runs.forEach(function (run) {
    const j = run.judgement;
    const p1 = run.core1.filter(function (r) { return r.pass; }).length;
    const p2 = run.core2.filter(function (r) { return r.pass; }).length;
    const pf = run.feat2.filter(function (r) { return r.pass; }).length;
    const smoke2 = run.core2.filter(function (r) { return r.smoke; });
    lines.push('| ' + run.label + ': Build 1.0.0 sheet on v1 | all ' + run.core1.length + ' rows pass | ' + p1 + '/' + run.core1.length + ' pass, ' + mark(j.v1AllPass) + ' |');
    lines.push('| ' + run.label + ': Build 1.1.0 sheet on v2 | only ' + j.expectedV2.join(', ') + ' fail | ' + p2 + '/' + run.core2.length + ' pass, failed: ' + (j.failedV2.join(', ') || 'none') + ', ' + mark(j.v2ExactFails) + ' |');
    lines.push('| ' + run.label + ': smoke rows on v2 | all ' + smoke2.length + ' pass | ' + smoke2.filter(function (r) { return r.pass; }).length + '/' + smoke2.length + ' pass, ' + mark(j.v2SmokePass) + ' |');
    lines.push('| ' + run.label + ': new feature rows on v2 | all ' + run.feat2.length + ' pass | ' + pf + '/' + run.feat2.length + ' pass, ' + mark(j.featureAllPass) + ' |');
  });
  const auditPass = audit.filter(function (a) { return a.pass; }).length;
  lines.push('| Banner and build label on every page | ' + audit.length + ' pages | ' + auditPass + '/' + audit.length + ' pass, ' + mark(auditPass === audit.length) + ' |');
  lines.push('| Requests to external domains | none | ' + externalRequests.size + ', ' + mark(externalRequests.size === 0) + ' |');
  lines.push('| Revealing words, absolute URLs, alert(), randomness in deployed files | none in ' + scan.files + ' files | ' + scan.findings.length + ' findings, ' + mark(scan.findings.length === 0) + ' |');
  lines.push('| Test sheet structure (3 workbooks) | all checks pass | ' + sheets.checks.filter(function (c) { return c.ok; }).length + '/' + sheets.checks.length + ' pass, ' + mark(sheets.ok) + ' |');
  lines.push('');

  lines.push('## Core rows (' + main.label + ')', '');
  lines.push('| StepID | Feature | Smoke | Build 1.0.0 (v1) | Build 1.1.0 (v2) | Detail on v2 failure |', '|---|---|---|---|---|---|');
  main.core1.forEach(function (r1, i) {
    const r2 = main.core2[i];
    lines.push('| ' + r1.id + ' | ' + cell(r1.feature) + ' | ' + (r1.smoke ? 'Yes' : 'No') + ' | ' + mark(r1.pass) + (r1.pass ? '' : ': ' + cell(r1.error)) + ' | ' + mark(r2.pass) + ' | ' + cell(r2.pass ? '' : r2.error) + ' |');
  });
  lines.push('');

  lines.push('## New feature rows (' + main.label + ')', '');
  lines.push('| StepID | Build 1.1.0 (v2) | Build 1.0.0 (v1, control: feature absent) |', '|---|---|---|');
  main.feat2.forEach(function (r, i) {
    const control = main.feat1[i];
    lines.push('| ' + r.id + ' | ' + mark(r.pass) + (r.pass ? '' : ': ' + cell(r.error)) + ' | ' + (control.pass ? 'PASS' : 'FAIL (expected)') + ' |');
  });
  lines.push('');

  lines.push('## Page audit', '');
  lines.push('Each page was opened (signed-in pages with `?as=tester`; the OTP page through a real login). Checked: the banner text is visible at the very top, the footer reads the right build label, every input/select/textarea has a `<label for>`, and there are no page errors, console errors, dialogs or external requests.', '');
  lines.push('| Page | Result | Notes |', '|---|---|---|');
  audit.forEach(function (a) { lines.push('| ' + a.page + ' | ' + mark(a.pass) + ' | ' + cell(a.notes) + ' |'); });
  lines.push('');

  lines.push('## Deployed file scan', '');
  lines.push('Scanned ' + scan.files + ' files under `docs/` (contents and file names) for words that could reveal the Build 1.1.0 changes, absolute URLs, `alert()`/`confirm()`/`prompt()`, `Math.random`, images, iframes, CSS imports and leftover build tokens.', '');
  lines.push(scan.findings.length ? scan.findings.map(function (f) { return '- ' + f; }).join('\n') : 'No findings.');
  lines.push('');
  lines.push('External requests seen across every run: ' + (externalRequests.size ? Array.from(externalRequests).join(', ') : 'none') + '.', '');

  lines.push('## Test sheet checks', '');
  lines.push('| Check | Result | Detail |', '|---|---|---|');
  sheets.checks.forEach(function (c) { lines.push('| ' + cell(c.name) + ' | ' + mark(c.ok) + ' | ' + cell(c.detail) + ' |'); });
  lines.push('');

  fs.writeFileSync(path.join(ROOT, 'VERIFY_REPORT.md'), lines.join('\n'), 'utf8');
  return verdict;
}

/* ---------------- main ---------------- */

async function runBrowser(launcher, options, label, base) {
  const browser = await launcher.launch(options);
  const core1 = await runSuite(browser, base, 'v1', ROWS.core, 'core');
  const core2 = await runSuite(browser, base, 'v2', ROWS.core, 'core');
  const feat2 = await runSuite(browser, base, 'v2', ROWS.feature, 'feature');
  const feat1 = await runSuite(browser, base, 'v1', ROWS.feature, 'feature-control');
  const version = browser.version();
  await browser.close();
  const run = { label: label + ' ' + version, core1: core1, core2: core2, feat2: feat2, feat1: feat1 };
  run.judgement = judge(core1, core2, feat2);
  return run;
}

async function main() {
  fs.rmSync(OUT, { recursive: true, force: true });
  const server = await startServer();
  const base = 'http://127.0.0.1:' + server.address().port;
  const runs = [];

  runs.push(await runBrowser(playwright.chromium, {}, 'Chromium', base));
  if (process.argv.indexOf('--no-edge') === -1) {
    try {
      runs.push(await runBrowser(playwright.chromium, { channel: 'msedge' }, 'Microsoft Edge', base));
    } catch (e) {
      console.log('Microsoft Edge not available, skipped: ' + e.message.split('\n')[0]);
    }
  }

  const liveIndex = process.argv.indexOf('--live');
  if (liveIndex !== -1) {
    const live = process.argv[liveIndex + 1].replace(/\/+$/, '');
    allowedHosts.add(new URL(live).hostname);
    const useEdge = runs.some(function (r) { return r.label.indexOf('Edge') === 0; });
    runs.push(await runBrowser(playwright.chromium, useEdge ? { channel: 'msedge' } : {}, (useEdge ? 'Microsoft Edge' : 'Chromium') + ' (live GitHub Pages)', live));
  }

  const browser = await playwright.chromium.launch();
  const audit = await auditPages(browser, base);
  await browser.close();
  server.close();

  const scan = scanDeployedFiles();
  const sheets = checkSheets();
  const info = {
    date: new Date().toISOString().replace('T', ' ').slice(0, 16) + ' UTC',
    playwright: PLAYWRIGHT_VERSION,
    live: liveIndex !== -1 ? process.argv[liveIndex + 1] : ''
  };
  const ok = writeReport(runs, audit, scan, sheets, info);

  runs.forEach(function (run) {
    const j = run.judgement;
    console.log(run.label + ': v1 ' + run.core1.filter(function (r) { return r.pass; }).length + '/' + run.core1.length +
      ', v2 failed [' + j.failedV2.join(', ') + '] (expected [' + j.expectedV2.join(', ') + '])' +
      ', feature rows on v2 ' + run.feat2.filter(function (r) { return r.pass; }).length + '/' + run.feat2.length);
    run.core1.concat(run.feat2).filter(function (r) { return !r.pass; }).forEach(function (r) { console.log('   unexpected fail ' + r.id + ': ' + r.error); });
    run.core2.filter(function (r) { return !r.pass; }).forEach(function (r) { console.log('   v2 fail ' + r.id + ': ' + r.error); });
  });
  console.log('Page audit: ' + audit.filter(function (a) { return a.pass; }).length + '/' + audit.length);
  audit.filter(function (a) { return !a.pass; }).forEach(function (a) { console.log('   ' + a.page + ': ' + a.notes); });
  console.log('External requests: ' + externalRequests.size + ', scan findings: ' + scan.findings.length);
  scan.findings.forEach(function (f) { console.log('   ' + f); });
  console.log('Sheet checks: ' + (sheets.ok ? 'ok' : 'FAILED'));
  sheets.checks.filter(function (c) { return !c.ok; }).forEach(function (c) { console.log('   ' + c.name + ': ' + c.detail); });
  console.log(ok ? 'OVERALL: PASS' : 'OVERALL: FAIL');
  console.log('Report written to VERIFY_REPORT.md');
  process.exitCode = ok ? 0 : 1;
}

main().catch(function (e) {
  console.error(e);
  process.exitCode = 1;
});
